begin;
    with j as (select * from jsonb_to_recordset($law7v013$[{"code_id":"GK_RF_2","article_number":"481","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено договором купли-продажи и не вытекает из существа обязательства, продавец обязан передать покупателю товар в таре и (или) упаковке, за исключением товара, который по своему характеру не требует затаривания и (или) упаковки.\n\n2. Если договором купли-продажи не определены требования к таре и упаковке, то товар должен быть затарен и (или) упакован обычным для такого товара способом, а при отсутствии такового способом, обеспечивающим сохранность товаров такого рода при обычных условиях хранения и транспортирования.\n\n3. Если в установленном законом порядке предусмотрены обязательные требования к таре и (или) упаковке, то продавец, осуществляющий предпринимательскую деятельность, обязан передать покупателю товар в таре и (или) упаковке, соответствующих этим обязательным требованиям.","article_title":"Статья 481. Тара и упаковка","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0d2af9c2908f98769b9abeadb0aebcb567fbf019e8814a83cbf5df229f7c8517"},{"code_id":"GK_RF_2","article_number":"482","version_date":"1994-11-30","article_text":"1. В случаях, когда подлежащий затариванию и (или) упаковке товар передается покупателю без тары и (или) упаковки либо в ненадлежащей таре и (или) упаковке, покупатель вправе потребовать от продавца затарить и (или) упаковать товар либо заменить ненадлежащую тару и (или) упаковку, если иное не вытекает из договора, существа обязательства или характера товара.\n\n2. В случаях, предусмотренных пунктом 1 настоящей статьи, покупатель вправе вместо предъявления продавцу требований, указанных в этом пункте, предъявить к нему требования, вытекающие из передачи товара ненадлежащего качества (статья 475).","article_title":"Статья 482. Последствия передачи товара без тары и (или) упаковки либо в ненадлежащей таре и (или) упаковке","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9fafabd127e880a33cf5042c83a7677a77cb7cc90365d1f2ed07c0705a1d5e7d"},{"code_id":"GK_RF_2","article_number":"483","version_date":"1994-11-30","article_text":"1. Покупатель обязан известить продавца о нарушении условий договора купли-продажи о количестве, об ассортименте, о качестве, комплектности, таре и (или) об упаковке товара в срок, предусмотренный законом, иными правовыми актами или договором, а если такой срок не установлен, в разумный срок после того, как нарушение соответствующего условия договора должно было быть обнаружено исходя из характера и назначения товара.\n\n2. В случае невыполнения правила, предусмотренного пунктом 1 настоящей статьи, продавец вправе отказаться полностью или частично от удовлетворения требований покупателя о передаче ему недостающего количества товара, замене товара, не соответствующего условиям договора купли-продажи о качестве или об ассортименте, об устранении недостатков товара, о доукомплектовании товара или о замене некомплектного товара комплектным, о затаривании и (или) об упаковке товара либо о замене ненадлежащей тары и (или) упаковки товара, если докажет, что невыполнение этого правила покупателем повлекло невозможность удовлетворить его требования или влечет для продавца несоизмеримые расходы по сравнению с теми, которые он понес бы, если бы был своевременно извещен о нарушении договора.\n\n3. Если продавец знал или должен был знать о том, что переданные покупателю товары не соответствуют условиям договора купли-продажи, он не вправе ссылаться на положения, предусмотренные пунктами 1 и 2 настоящей статьи.","article_title":"Статья 483. Извещение продавца о ненадлежащем исполнении договора купли-продажи","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"05ea481ec88f1f7b15df958074b80d11c8af3fd8679d35428eb71516a3906821"},{"code_id":"GK_RF_2","article_number":"484","version_date":"1994-11-30","article_text":"1. Покупатель обязан принять переданный ему товар, за исключением случаев, когда он вправе потребовать замены товара или отказаться от исполнения договора купли-продажи.\n\n2. Если иное не предусмотрено законом, иными правовыми актами или договором купли-продажи, покупатель обязан совершить действия, которые в соответствии с обычно предъявляемыми требованиями необходимы с его стороны для обеспечения передачи и получения соответствующего товара.\n\n3. В случаях, когда покупатель в нарушение закона, иных правовых актов или договора купли-продажи не принимает товар или отказывается его принять, продавец вправе потребовать от покупателя принять товар или отказаться от исполнения договора.","article_title":"Статья 484. Обязанность покупателя принять товар","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e6c3b2e16fe041880daa0299443b4d5f2ed173e5fd21691d0cfc46d08a389d7f"},{"code_id":"GK_RF_2","article_number":"485","version_date":"1994-11-30","article_text":"1. Покупатель обязан оплатить товар по цене, предусмотренной договором купли-продажи, либо, если она договором не предусмотрена и не может быть определена исходя из его условий, по цене, определяемой в соответствии с пунктом 3 статьи 424 настоящего Кодекса, а также совершить за свой счет действия, которые в соответствии с законом, иными правовыми актами, договором или обычно предъявляемыми требованиями необходимы для осуществления платежа.\n\n2. Когда цена установлена в зависимости от веса товара, она определяется по весу нетто, если иное не предусмотрено договором купли-продажи.\n\n3. Если договор купли-продажи предусматривает, что цена товара подлежит изменению в зависимости от показателей, обусловливающих цену товара (себестоимость, затраты и т.п.), но при этом не определен способ пересмотра цены, цена определяется исходя из соотношения этих показателей на момент заключения договора и на момент передачи товара. При просрочке продавцом исполнения обязанности передать товар цена определяется исходя из соотношения этих показателей на момент заключения договора и на момент передачи товара, предусмотренный договором, а если он договором не предусмотрен, на момент, определенный в соответствии со статьей 314 настоящего Кодекса.\n\nПравила, предусмотренные настоящим пунктом, применяются, если иное не установлено настоящим Кодексом, другим законом, иными правовыми актами или договором и не вытекает из существа обязательства.","article_title":"Статья 485. Цена товара","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"24320cb9cd76a4a2c079963a2d2489b7c50298564c764bb9e7aa981881175526"},{"code_id":"GK_RF_2","article_number":"486","version_date":"1994-11-30","article_text":"1. Покупатель обязан оплатить товар непосредственно до или после передачи ему продавцом товара, если иное не предусмотрено настоящим Кодексом, другим законом, иными правовыми актами или договором купли-продажи и не вытекает из существа обязательства.\n\n2. Если договором купли-продажи не предусмотрена рассрочка оплаты товара, покупатель обязан уплатить продавцу цену переданного товара полностью.\n\n3. Если покупатель своевременно не оплачивает переданный в соответствии с договором купли-продажи товар, продавец вправе потребовать оплаты товара и уплаты процентов в соответствии со статьей 395 настоящего Кодекса.\n\n4. Если покупатель в нарушение договора купли-продажи отказывается принять и оплатить товар, продавец вправе по своему выбору потребовать оплаты товара либо отказаться от исполнения договора.\n\n5. В случаях, когда продавец в соответствии с договором купли-продажи обязан передать покупателю не только товары, которые покупателем не оплачены, но и другие товары, продавец вправе приостановить передачу этих товаров до полной оплаты всех ранее переданных товаров, если иное не предусмотрено законом, иными правовыми актами или договором.","article_title":"Статья 486. Оплата товара","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6a5a3fdda56ae1222a670bca59a252ebd3ca5c243b043366f7563d1c32ae24c6"},{"code_id":"GK_RF_2","article_number":"487","version_date":"1994-11-30","article_text":"1. В случаях, когда договором купли-продажи предусмотрена обязанность покупателя оплатить товар полностью или частично до передачи продавцом товара (предварительная оплата), покупатель должен произвести оплату в срок, предусмотренный договором, а если такой срок договором не предусмотрен, в срок, определенный в соответствии со статьей 314 настоящего Кодекса.\n\n2. В случае неисполнения покупателем обязанности предварительно оплатить товар применяются правила, предусмотренные статьей 328 настоящего Кодекса.\n\n3. В случае, когда продавец, получивший сумму предварительной оплаты, не исполняет обязанность по передаче товара в установленный срок (статья 457), покупатель вправе потребовать передачи оплаченного товара или возврата суммы предварительной оплаты за товар, не переданный продавцом.","article_title":"Статья 487. Предварительная оплата товара","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"13a290f2c150f47308fa6b7cc7f4d015e3a0145b90442a03870695a22d5eeeed"},{"code_id":"GK_RF_2","article_number":"488","version_date":"1994-11-30","article_text":"1. В случае, когда договором купли-продажи предусмотрена оплата товара через определенное время после его передачи покупателю (продажа товара в кредит), покупатель должен произвести оплату в срок, предусмотренный договором, а если такой срок договором не предусмотрен, в срок, определенный в соответствии со статьей 314 настоящего Кодекса.\n\n2. В случае неисполнения продавцом обязанности по передаче товара применяются правила, предусмотренные статьей 328 настоящего Кодекса.\n\n3. В случае, когда покупатель, получивший товар, не исполняет обязанность по его оплате в установленный договором купли-продажи срок, продавец вправе потребовать оплаты переданного товара или возврата неоплаченных товаров.\n\n4. В случае, когда покупатель не исполняет обязанность по оплате переданного товара в установленный договором срок и иное не предусмотрено настоящим Кодексом или договором купли-продажи, на просроченную сумму подлежат уплате проценты в соответствии со статьей 395 настоящего Кодекса со дня, когда по договору товар должен был быть оплачен, до дня оплаты товара покупателем.\n\nДоговором может быть предусмотрена обязанность покупателя уплачивать проценты на сумму, соответствующую цене товара, начиная со дня передачи товара продавцом.\n\n5. Если иное не предусмотрено договором купли-продажи, с момента передачи товара покупателю и до его оплаты товар, проданный в кредит, признается находящимся в залоге у продавца для обеспечения исполнения покупателем его обязанности по оплате товара.","article_title":"Статья 488. Оплата товара, проданного в кредит","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f377531f3576d36ab9ee497c1b1733d5e9f8244c9c238df07fe3d76afdc7c3ce"},{"code_id":"GK_RF_2","article_number":"489","version_date":"1994-11-30","article_text":"1. Договором о продаже товара в кредит может быть предусмотрена оплата товара в рассрочку.\n\nДоговор о продаже товара в кредит с условием о рассрочке платежа считается заключенным, если в нем наряду с другими существенными условиями договора купли-продажи указаны цена товара, порядок, сроки и размеры платежей.\n\n2. Когда покупатель не производит в установленный договором срок очередной платеж за проданный в рассрочку и переданный ему товар, продавец вправе, если иное не предусмотрено договором, отказаться от исполнения договора и потребовать возврата проданного товара, за исключением случаев, когда сумма платежей, полученных от покупателя, превышает половину цены товара.\n\n3. К договору о продаже товара в кредит с условием о рассрочке платежа применяются правила, предусмотренные пунктами 2, 4 и 5 статьи 488 настоящего Кодекса.","article_title":"Статья 489. Оплата товара в рассрочку","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ab58c7e0cfef8131104fc7fddbf7ad4efd18782728ed5f67c38854071eaed307"},{"code_id":"GK_RF_2","article_number":"490","version_date":"1994-11-30","article_text":"Договором купли-продажи может быть предусмотрена обязанность продавца или покупателя страховать товар.\n\nВ случае, когда сторона, обязанная страховать товар, не осуществляет страхование в соответствии с условиями договора, другая сторона вправе застраховать товар и потребовать от обязанной стороны возмещения расходов на страхование либо отказаться от исполнения договора.","article_title":"Статья 490. Страхование товара","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"863994778930e7315e0079b4b1a0e0246a397518f31fa0a33d88a2b64ef7607e"},{"code_id":"GK_RF_2","article_number":"491","version_date":"1994-11-30","article_text":"В случаях, когда договором купли-продажи предусмотрено, что право собственности на переданный покупателю товар сохраняется за продавцом до оплаты товара или наступления иных обстоятельств, покупатель не вправе до перехода к нему права собственности отчуждать товар или распоряжаться им иным образом, если иное не предусмотрено законом или договором либо не вытекает из назначения и свойств товара.\n\nВ случаях, когда в срок, предусмотренный договором, переданный товар не будет оплачен или не наступят иные обстоятельства, при которых право собственности переходит к покупателю, продавец вправе потребовать от покупателя возвратить ему товар, если иное не предусмотрено договором.","article_title":"Статья 491. Сохранение права собственности за продавцом","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"21467a65c79cfe98cf41a6512cafd2156cd09a09dcd890abd52473e431140d3d"},{"code_id":"GK_RF_2","article_number":"492","version_date":"1994-11-30","article_text":"1. По договору розничной купли-продажи продавец, осуществляющий предпринимательскую деятельность по продаже товаров в розницу, обязуется передать покупателю товар, предназначенный для личного, семейн\n\nого, домашнего или иного использования, не связанного с предпринимательской деятельностью.\n\n2. Договор розничной купли-продажи является публичным договором (статья 426).\n\n3. К отношениям по договору розничной купли-продажи с участием покупателя-гражданина, не урегулированным настоящим Кодексом, применяются законы о защите прав потребителей и иные правовые акты, принятые в соответствии с ними.","article_title":"Статья 492. Договор розничной купли-продажи","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5dff78c41bc0898198ea2307a05c3c9c57602ed479c2b56c6704d36655837d13"},{"code_id":"GK_RF_2","article_number":"493","version_date":"1994-11-30","article_text":"Если иное не предусмотрено законом или договором розничной купли-продажи, в том числе условиями формуляров или иных стандартных форм, к которым присоединяется покупатель (статья 428), договор розничной купли-продажи считается заключенным в надлежащей форме с момента выдачи продавцом покупателю кассового или товарного чека, электронного или иного документа, подтверждающего оплату товара. Отсутствие у покупателя указанных документов не лишает его возможности ссылаться на свидетельские показания в подтверждение заключения договора и его условий. (В редакции Федерального закона от 18.03.2019 № 34-ФЗ)","article_title":"Статья 493. Форма договора розничной купли-продажи","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0a80fced06cc10aa8dd9db8d879d7169aa842ae1bdcc43165586eba2ca87ba76"},{"code_id":"GK_RF_2","article_number":"494","version_date":"1994-11-30","article_text":"1. Предложение товара в его рекламе, каталогах и описаниях товаров, обращенных к неопределенному кругу лиц, признается публичной офертой (пункт 2 статьи 437), если оно содержит все существенные условия договора розничной купли-продажи.","article_title":"Статья 494. Публичная оферта товара","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7344438cdb7c03c89bd30b0509f6c2bb5c22ea615f3f7e84e4ec8f4d162e82b3"},{"code_id":"GK_RF_2","article_number":"495","version_date":"1994-11-30","article_text":"1. Продавец обязан предоставить покупателю необходимую и достоверную информацию о товаре, предлагаемом к продаже, соответствующую установленным законом, иными правовыми актами и обычно предъявляемым в розничной торговле требованиям к содержанию и способам предоставления такой информации.\n\n2. Покупатель вправе до заключения договора розничной купли-продажи осмотреть товар, потребовать проведения в его присутствии проверки свойств или демонстрации использования товара, если это не исключено ввиду характера товара и не противоречит правилам, принятым в розничной торговле.\n\n3. Если покупателю не предоставлена возможность незамедлительно получить в месте продажи информацию о товаре, указанную в пунктах 1 и 2 настоящей статьи, он вправе потребовать от продавца возмещения убытков, вызванных необоснованным уклонением от заключения договора розничной купли-продажи (пункт 4 статьи 445), а если договор заключен, в разумный срок отказаться от исполнения договора, потребовать возврата уплаченной за товар суммы и возмещения других убытков.\n\n4. Продавец, не предоставивший покупателю возможность получить соответствующую информацию о товаре, несет ответственность и за недостатки товара, возникшие после его передачи покупателю, в отношении которых покупатель докажет, что они возникли в связи с отсутствием у него такой информации.","article_title":"Статья 495. Предоставление покупателю информации о товаре","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"87b8066fba162ad99c9fcfe36ebfb2c6255ad8a0721e1fe2414e4f204fd82210"},{"code_id":"GK_RF_2","article_number":"496","version_date":"1994-11-30","article_text":"Договор розничной купли-продажи может быть заключен с условием о принятии покупателем товара в определенный договором срок, в течение которого этот товар не может быть продан другому покупателю.\n\nЕсли иное не предусмотрено договором, неявка покупателя или несовершение иных необходимых действий для принятия товара в определенный договором срок могут рассматриваться продавцом в качестве отказа покупателя от исполнения договора.\n\nДополнительные расходы продавца на обеспечение передачи товара покупателю в определенный договором срок включаются в цену товара, если иное не предусмотрено законом, иными правовыми актами или договором.","article_title":"Статья 496. Продажа товара с условием о его принятии покупателем в определенный срок","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"af0fc31057392d9116ebfbacc8d0242c08b850b3f4b446587aa34d4c1641948b"},{"code_id":"GK_RF_2","article_number":"497","version_date":"1994-11-30","article_text":"1. Договор розничной купли-продажи может быть заключен на основании ознакомления покупателя с образцом товара, предложенным продавцом и выставленным в месте продажи товаров (продажа товара по образцам).\n\n2. Договор розничной купли-продажи может быть заключен на основании ознакомления покупателя с предложенным продавцом описанием товара посредством каталогов, проспектов, буклетов, фотоснимков, средств связи (телевизионной, почтовой, радиосвязи и других) или иными способами, исключающими возможность непосредственного ознакомления потребителя с товаром либо образцом товара при заключении такого договора (дистанционный способ продажи товара).\n\n3. Если иное не предусмотрено законом, иными правовыми актами или договором, договор розничной купли-продажи товара по образцам или договор розничной купли-продажи, заключенный дистанционным способом продажи товара, считается исполненным с момента доставки товара в место, указанное в таком договоре, а если место передачи товара таким договором не определено, с момента доставки товара по месту жительства покупателя-гражданина или месту нахождения покупателя - юридического лица.\n\n4. Если иное не предусмотрено законом, до передачи товара покупатель вправе отказаться от исполнения любого указанного в пункте 3 настоящей статьи договора розничной купли-продажи при условии возмещения продавцу необходимых расходов, понесенных в связи с совершением действий по исполнению договора.\n\n(Статья в редакции Федерального закона от 25.10.2007 № 234-ФЗ)","article_title":"Статья 497. Продажа товара по образцам и дистанционный способ продажи товара","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9358b221f566842b9828efb1cab976abf87ed9dec10fd9f7895e96645d5be7c4"},{"code_id":"GK_RF_2","article_number":"498","version_date":"1994-11-30","article_text":"1. В случаях, когда продажа товаров производится с использованием автоматов, владелец автоматов обязан довести до покупателей информацию о продавце товаров путем помещения на автомате или предоставления покупателям иным способом сведений о наименовании (фирменном наименовании) продавца, месте его нахождения, режиме работы, а также о действиях, которые необходимо совершить покупателю для получения товара.\n\n2. Договор розничной купли-продажи с использованием автоматов считается заключенным с момента совершения покупателем действий, необходимых для получения товара.\n\n3. Если покупателю не предоставляется оплаченный товар, продавец обязан по требованию покупателя незамедлительно предоставить покупателю товар или возвратить уплаченную им сумму.\n\n4. В случаях, когда автомат используется для размена денег, приобретения знаков оплаты или обмена валюты, применяются правила о розничной купле-продаже, если иное не вытекает из существа обязательства.","article_title":"Статья 498. Продажа товаров с использованием автоматов","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"811ae47078a406ba32d58cccbc853c41125a08a741528f4e08a4b243e42a1936"},{"code_id":"GK_RF_2","article_number":"499","version_date":"1994-11-30","article_text":"1. В случае, когда договор розничной купли-продажи заключен с условием о доставке товара покупателю, продавец обязан в установленный договором срок доставить товар в место, указанное покупателем, а если место доставки товара покупателем не указано, в место жительства гражданина или место нахождения юридического лица, являющихся покупателями.\n\n2. Договор розничной купли-продажи считается исполненным с момента вручения товара покупателю, а при его отсутствии любому лицу, предъявившему квитанцию или иной документ, свидетельствующий о заключении договора или об оформлении доставки товара, если иное не предусмотрено законом, иными правовыми актами или договором либо не вытекает из существа обязательства.\n\n3. В случае, когда договором не определено время доставки товара для вручения его покупателю, товар должен быть доставлен в разумный срок после получения требования покупателя.","article_title":"Статья 499. Продажа товара с условием о его доставке покупателю","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8331b2689c736fd640439d426a54c843b135ff25009f347a3a453cf34a382111"},{"code_id":"GK_RF_2","article_number":"500","version_date":"1994-11-30","article_text":"1. Покупатель обязан оплатить товар по цене, объявленной продавцом в момент заключения договора розничной купли-продажи, если иное не предусмотрено законом, иными правовыми актами или не вытекает из существа обязательства.\n\n2. В случае, когда договором розничной купли-продажи предусмотрена предварительная оплата товара (статья 487), неоплата покупателем товара в установленный договором срок признается отказом покупателя от исполнения договора, если иное не предусмотрено соглашением сторон.\n\n3. К договорам розничной купли-продажи товаров в кредит, в том числе с условием оплаты покупателем товаров в рассрочку, не подлежат применению правила, предусмотренные абзацем первым пункта 4 статьи 488 настоящего Кодекса.\n\nПокупатель вправе оплатить товар в любое время в пределах установленного договором периода рассрочки оплаты товара.","article_title":"Статья 500. Цена и оплата товара","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4399393589bc15d493cc6ea93e5fb14415ed62285d38bdd1d77dd6714c24b5e4"},{"code_id":"GK_RF_2","article_number":"501","version_date":"1994-11-30","article_text":"Договором может быть предусмотрено, что до перехода права собственности на товар к покупателю (статья 491) покупатель является нанимателем (арендатором) переданного ему товара (договор найма-продажи).\n\nЕсли иное не предусмотрено договором, покупатель становится собственником товара с момента оплаты товара.","article_title":"Статья 501. Договор найма-продажи","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3c1da874f526004c4087e0a1498eaa4dc6da39f2591006e5d015cc5f22c46c20"},{"code_id":"GK_RF_2","article_number":"502","version_date":"1994-11-30","article_text":"1. Покупатель вправе в течение четырнадцати дней с момента передачи ему непродовольственного товара, если более длительный срок не объявлен продавцом, обменять купленный товар в месте покупки и иных местах, объявленных продавцом, на аналогичный товар других размера, формы, габарита, фасона, расцветки или комплектации, произведя в случае разницы в цене необходимый перерасчет с продавцом.\n\nПри отсутствии необходимого для обмена товара у продавца покупатель вправе возвратить приобретенный товар продавцу и получить уплаченную за него денежную сумму.\n\nТребование покупателя об обмене либо о возврате товара подлежит удовлетворению, если товар не был в употреблении, сохранены его потребительские свойства и имеются доказательства приобретения его у данного продавца.\n\n2. Перечень товаров, которые не подлежат обмену или возврату по указанным в настоящей статье основаниям, определяется в порядке, установленном законом или иными правовыми актами.","article_title":"Статья 502. Обмен товара","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3471f0aa2284c6c491c7b0892b942816b06c8e17291c297641392527356e0659"},{"code_id":"GK_RF_2","article_number":"503","version_date":"1994-11-30","article_text":"1. Покупатель, которому продан товар ненадлежащего качества, если его недостатки не были оговорены продавцом, по своему выбору вправе потребовать:\n\nзамены недоброкачественного товара товаром надлежащего качества;\n\nсоразмерного уменьшения покупной цены;\n\nнезамедлительного безвозмездного устранения недостатков товара;\n\nвозмещения расходов на устранение недостатков товара.\n\n2. В случае обнаружения недостатков товара, свойства которого не позволяют устранить их (продовольственные товары, товары бытовой химии и тому подобное), покупатель по своему выбору вправе потребовать замены такого товара товаром надлежащего качества или соразмерного уменьшения покупной цены.\n\n3. В отношении технически сложного товара покупатель вправе потребовать его замены или отказаться от исполнения договора розничной купли-продажи и потребовать возврата уплаченной за товар суммы в случае существенного нарушения требований к его качеству (пункт 2 статьи 475).\n\n4. Вместо предъявления указанных в пунктах 1 и 2 настоящей статьи требований покупатель вправе отказаться от исполнения договора розничной купли-продажи и потребовать возврата уплаченной за товар суммы.\n\n5. При отказе от исполнения договора розничной купли-продажи с требованием возврата уплаченной за товар суммы покупатель по требованию продавца и за его счет должен возвратить полученный товар ненадлежащего качества.\n\nПри возврате покупателю уплаченной за товар суммы продавец не вправе удерживать из нее сумму, на которую понизилась стоимость товара из-за полного или частичного использования товара, потери им товарного вида или подобных обстоятельств.\n\n6. Правила, предусмотренные настоящей статьей, применяются, если законами о защите прав потребителей не установлено иное.\n\n(Статья  в редакции Федерального закона от 25.10.2007 № 234-ФЗ)","article_title":"Статья 503. Права покупателя в случае продажи ему товара ненадлежащего качества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"848a014cd062e150d5927e3457eb67e463514f895bb74a0b8bc9b0cc6d0097d2"},{"code_id":"GK_RF_2","article_number":"504","version_date":"1994-11-30","article_text":"1. При замене недоброкачественного товара на соответствующий договору розничной купли-продажи товар надлежащего качества продавец не вправе требовать возмещения разницы между ценой товара, установленной договором, и ценой товара, существующей в момент замены товара или вынесения судом решения о замене товара.\n\n2. При замене недоброкачественного товара на аналогичный, но иной по размеру, фасону, сорту или другим признакам товар надлежащего качества подлежит возмещению разница между ценой заменяемого товара в момент замены и ценой товара, передаваемого взамен товара ненадлежащего качества.\n\nЕсли требование покупателя не удовлетворено продавцом, цена заменяемого товара и цена товара, передаваемого взамен него, определяются на момент вынесения судом решения о замене товара.\n\n3. В случае предъявления требования о соразмерном уменьшении покупной цены товара в расчет принимается цена товара на момент предъявления требования об уценке, а если требование покупателя добровольно не удовлетворено, на момент вынесения судом решения о соразмерном уменьшении цены.\n\n4. При возврате продавцу товара ненадлежащего качества покупатель вправе потребовать возмещения разницы между ценой товара, установленной договором розничной купли-продажи, и ценой соответствующего товара на момент добровольного удовлетворения его требования, а если требование добровольно не удовлетворено, на момент вынесения судом решения.","article_title":"Статья 504. Возмещение разницы в цене при замене товара, уменьшении покупной цены и возврате товара ненадлежащего качества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"90f38d23c0a67cf531bcec0d9e81131012e66191b8f092dfccfd96b51fa53ef3"},{"code_id":"GK_RF_2","article_number":"505","version_date":"1994-11-30","article_text":"В случае неисполнения продавцом обязательства по договору розничной купли-продажи возмещение убытков и уплата неустойки не освобождают продавца от исполнения обязательства в натуре.","article_title":"Статья 505. Ответственность продавца и исполнение обязательства в натуре","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0399bb16bfaa1445f58d1c6264888f770131b57fb5124f6705667013fd3d80fa"},{"code_id":"GK_RF_2","article_number":"506","version_date":"1994-11-30","article_text":"По договору поставки поставщик - продавец, осуществляющий предпринимательскую деятельность, обязуется передать в обусловленный срок или сроки производимые или закупаемые им товары покупателю для использования в предпринимательской деятельности или в иных целях, не связанных с личным, семейным, домашним и иным подобным использованием.","article_title":"Статья 506. Договор поставки","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"96ae0a9dc7eeae2d8c21fbe7bd23902ae98bd2b34d908bb7aea713357bb46722"},{"code_id":"GK_RF_2","article_number":"507","version_date":"1994-11-30","article_text":"1. В случае, когда при заключении договора поставки между сторонами возникли разногласия по отдельным условиям договора, сторона, предложившая заключить договор и получившая от другой стороны предложение о согласовании этих условий, должна в течение тридцати дней со дня получения этого предложения, если иной срок не установлен законом или не согласован сторонами, принять меры по согласованию соответствующих условий договора либо письменно уведомить другую сторону об отказе от его заключения.\n\n2. Сторона, получившая предложение по соответствующим условиям договора, но не принявшая мер по согласованию условий договора поставки и не уведомившая другую сторону об отказе от заключения договора в срок, предусмотренный пунктом 1 настоящей статьи, обязана возместить убытки, вызванные уклонением от согласования условий договора.","article_title":"Статья 507. Урегулирование разногласий при заключении договора поставки","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"abfe68b70b2c4ed35df1f52c1008cd033867cb3decfdc5c993b4884b1f03cd2b"},{"code_id":"GK_RF_2","article_number":"508","version_date":"1994-11-30","article_text":"1. В случае, когда сторонами предусмотрена поставка товаров в течение срока действия договора поставки отдельными партиями и сроки поставки отдельных партий (периоды поставки) в нем не определены, то товары должны поставляться равномерными партиями помесячно, если иное не вытекает из закона, иных правовых актов, существа обязательства или обычаев делового оборота.\n\n2. Наряду с определением периодов поставки в договоре поставки может быть установлен график поставки товаров (декадный, суточный, часовой и т.п.).\n\n3. Досрочная поставка товаров может производиться с согласия покупателя.\n\nТовары, поставленные досрочно и принятые покупателем, засчитываются в счет количества товаров, подлежащих поставке в следующем периоде.","article_title":"Статья 508. Периоды поставки товаров","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c558b836ed703bb1b076eb63ba6d368922c727ee49138807adcec9c472999281"},{"code_id":"GK_RF_2","article_number":"509","version_date":"1994-11-30","article_text":"1. Поставка товаров осуществляется поставщиком путем отгрузки (передачи) товаров покупателю, являющемуся стороной договора поставки, или лицу, указанному в договоре в качестве получателя.\n\n2. В случае, когда договором поставки предусмотрено право покупателя давать поставщику указания об отгрузке (передаче) товаров получателям (отгрузочные разнарядки), отгрузка (передача) товаров осуществляется поставщиком получателям, указанным в отгрузочной разнарядке.\n\nСодержание отгрузочной разнарядки и срок ее направления покупателем поставщику определяются договором. Если срок направления отгрузочной разнарядки договором не предусмотрен, она должна быть направлена поставщику не позднее чем за тридцать дней до наступления периода поставки.\n\n3. Непредставление покупателем отгрузочной разнарядки в установленный срок дает поставщику право либо отказаться от исполнения договора поставки, либо потребовать от покупателя оплаты товаров. Кроме того, поставщик вправе потребовать возмещения убытков, причиненных в связи с непредставлением отгрузочной разнарядки.","article_title":"Статья 509. Порядок поставки товаров","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"86c5e8544780593c58d2eb8a43dce9f5a76afd7ee125679c4bd27ca97f0d19e4"},{"code_id":"GK_RF_2","article_number":"510","version_date":"1994-11-30","article_text":"1. Доставка товаров осуществляется поставщиком путем отгрузки их транспортом, предусмотренным договором поставки, и на определенных в договоре условиях.\n\nВ случаях, когда в договоре не определено, каким видом транспорта или на каких условиях осуществляется доставка, право выбора вида транспорта или определения условий доставки товаров принадлежит поставщику, если иное не вытекает из закона, иных правовых актов, существа обязательства или обычаев делового оборота.\n\n2. Договором поставки может быть предусмотрено получение товаров покупателем (получателем) в месте нахождения поставщика (выборка товаров).\n\nЕсли срок выборки не предусмотрен договором, выборка товаров покупателем (получателем) должна производиться в разумный срок после получения уведомления поставщика о готовности товаров.","article_title":"Статья 510. Доставка товаров","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"72463610411fab71e9b14755848d7bfe35b33e18229c68ff04611443059762e3"},{"code_id":"GK_RF_2","article_number":"511","version_date":"1994-11-30","article_text":"1. Поставщик, допустивший недопоставку товаров в отдельном периоде поставки, обязан восполнить недопоставленное количество товаров в следующем периоде (периодах) в пределах срока действия договора поставки, если иное не предусмотрено договором.\n\n2. В случае, когда товары отгружаются поставщиком нескольким получателям, указанным в договоре поставки или отгрузочной разнарядке покупателя, товары, поставленные одному получателю сверх количества, предусмотренного в договоре или отгрузочной разнарядке, не засчитываются в покрытие недопоставки другим получателям, если иное не предусмотрено в договоре.\n\n3. Покупатель вправе, уведомив поставщика, отказаться от принятия товаров, поставка которых просрочена, если в договоре поставки не предусмотрено иное. Товары, поставленные до получения поставщиком уведомления, покупатель обязан принять и оплатить.","article_title":"Статья 511. Восполнение недопоставки товаров","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c9536c353996e2d4bb7f2864238b962c8d4e3b1e2c65494f7cea4d25b54b74d8"},{"code_id":"GK_RF_2","article_number":"512","version_date":"1994-11-30","article_text":"1. Ассортимент товаров, недопоставка которых подлежит восполнению, определяется соглашением сторон. При отсутствии такого соглашения поставщик обязан восполнить недопоставленное количество товаров в ассортименте, установленном для того периода, в котором допущена недопоставка.\n\n2. Поставка товаров одного наименования в большем количестве, чем предусмотрено договором поставки, не засчитывается в покрытие недопоставки товаров другого наименования, входящих в тот же ассортимент, и подлежит восполнению, кроме случаев, когда такая поставка произведена с предварительного письменного согласия покупателя.","article_title":"Статья 512. Ассортимент товаров при восполнении недопоставки","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0c4d11e359543dca2f97b3e8f2ed3653847a8fcb0469b09cd5c2bf6559ae7437"},{"code_id":"GK_RF_2","article_number":"513","version_date":"1994-11-30","article_text":"1. Покупатель (получатель) обязан совершить все необходимые действия, обеспечивающие принятие товаров, поставленных в соответствии с договором поставки.\n\n2. Принятые покупателем (получателем) товары должны быть им\n\nосмотрены в срок, определенный законом, иными правовыми актами, договором поставки или обычаями делового оборота.\n\nПокупатель (получатель) обязан в этот же срок проверить количество и качество принятых товаров в порядке, установленном законом, иными правовыми актами, договором или обычаями делового оборота, и о выявленных несоответствиях или недостатках товаров незамедлительно письменно уведомить поставщика.\n\n3. В случае получения поставленных товаров от транспортной организации покупатель (получатель) обязан проверить соответствие товаров сведениям, указанным в транспортных и сопроводительных документах, а также принять эти товары от транспортной организации с соблюдением правил, предусмотренных законами и иными правовыми актами, регулирующими деятельность транспорта.","article_title":"Статья 513. Принятие товаров покупателем","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d8e1b2f38a85c01148ab6c711c6b5798bbb0682c86a35fa0e5ac60fd4fed8fa5"},{"code_id":"GK_RF_2","article_number":"514","version_date":"1994-11-30","article_text":"1. Когда покупатель (получатель) в соответствии с законом, иными правовыми актами или договором поставки отказывается от переданного поставщиком товара, он обязан обеспечить сохранность этого товара (ответственное хранение) и незамедлительно уведомить поставщика.\n\n2. Поставщик обязан вывезти товар, принятый покупателем (получателем) на ответственное хранение, или распорядиться им в разумный срок.\n\nЕсли поставщик в этот срок не распорядится товаром, покупатель вправе реализовать товар или возвратить его поставщику.\n\n3. Необходимые расходы, понесенные покупателем в связи с принятием товара на ответственное хранение, реализацией товара или его возвратом продавцу, подлежат возмещению поставщиком.\n\nПри этом вырученное от реализации товара передается поставщику за вычетом причитающегося покупателю.\n\n4. В случаях, когда покупатель без установленных законом, иными правовыми актами или договором оснований не принимает товар от поставщика или отказывается от его принятия, поставщик вправе потребовать от покупателя оплаты товара.","article_title":"Статья 514. Ответственное хранение товара, не принятого покупателем","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"348bbdd5025ec30fe15bcf9c1b75260e00ce76408577a60c3cf4fe197d583130"},{"code_id":"GK_RF_2","article_number":"515","version_date":"1994-11-30","article_text":"1. Когда договором поставки предусмотрена выборка товаров покупателем (получателем) в месте нахождения поставщика (пункт 2 статьи 510), покупатель обязан осуществить осмотр передаваемых товаров в месте их передачи, если иное не предусмотрено законом, иными правовыми актами или не вытекает из существа обязательства.\n\n2. Невыборка покупателем (получателем) товаров в установленный договором поставки срок, а при его отсутствии в разумный срок после получения уведомления поставщика о готовности товаров дает поставщику право отказаться от исполнения договора либо потребовать от покупателя оплаты товаров.","article_title":"Статья 515. Выборка товаров","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cdc12b847311fa32f10b8cedd34f674409e6388d52ba0230c18bbb1cb6af1293"},{"code_id":"GK_RF_2","article_number":"516","version_date":"1994-11-30","article_text":"1. Покупатель оплачивает поставляемые товары с соблюдением порядка и формы расчетов, предусмотренных договором поставки. Если соглашением сторон порядок и форма расчетов не определены, то расчеты осуществляются платежными поручениями.\n\n2. Если договором поставки предусмотрено, что оплата товаров осуществляется получателем (плательщиком) и последний неосновательно отказался от оплаты либо не оплатил товары в установленный договором срок, поставщик вправе потребовать оплаты поставленных товаров от покупателя.\n\n3. В случае, когда в договоре поставки предусмотрена поставка товаров отдельными частями, входящими в комплект, оплата товаров покупателем производится после отгрузки (выборки) последней части, входящей в комплект, если иное не установлено договором.","article_title":"Статья 516. Расчеты за поставляемые товары","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e7dcd5be6b3a501d1bba4884575fb279e4f7c538f1514c2c01602666eed99996"},{"code_id":"GK_RF_2","article_number":"517","version_date":"1994-11-30","article_text":"Если иное не установлено договором поставки, покупатель (получатель) обязан возвратить поставщику многооборотную тару и средства пакетирования, в которых поступил товар, в порядке и в сроки, установленные законом, иными правовыми актами, принятыми в соответствии с ними обязательными правилами или договором.\n\nПрочая тара, а также упаковка товара подлежат возврату поставщику лишь в случаях, предусмотренных договором.","article_title":"Статья 517. Тара и упаковка","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"85f68ae6a26ad43274a456e3c7a0becc75bacb96571b515551249cd07188e664"},{"code_id":"GK_RF_2","article_number":"518","version_date":"1994-11-30","article_text":"1. Покупатель (получатель), которому поставлены товары ненадлежащего качества, вправе предъявить поставщику требования, предусмотренные статьей 475 настоящего Кодекса, за исключением случая, когда поставщик, получивший уведомление покупателя о недостатках поставленных товаров, без промедления заменит поставленные товары товарами надлежащего качества.\n\n2. Покупатель (получатель), осуществляющий продажу поставленных ему товаров в розницу, вправе требовать замены в разумный срок товара ненадлежащего качества, возвращенного потребителем, если иное не предусмотрено договором поставки.","article_title":"Статья 518. Последствия поставки товаров ненадлежащего качества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"660e95a2e368793eb2bc8eaf8a986f4fa0c79937dd8653a416214d2305a3c856"},{"code_id":"GK_RF_2","article_number":"519","version_date":"1994-11-30","article_text":"1. Покупатель (получатель), которому поставлены товары с нарушением условий договора поставки, требований закона, иных правовых актов либо обычно предъявляемых требований к комплектности, вправе предъявить поставщику требования, предусмотренные статьей 480 настоящего Кодекса, за исключением случая, когда поставщик, получивший уведомление покупателя о некомплектности поставленных товаров, без промедления доукомплектует товары либо заменит их комплектными товарами.\n\n2. Покупатель (получатель), осуществляющий продажу товаров в розницу, вправе требовать замены в разумный срок некомплектных товаров, возвращенных потребителем, комплектными, если иное не предусмотрено договором поставки.","article_title":"Статья 519. Последствия поставки некомплектных товаров","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d384f4516b27bcb75fcf98f5cd18be65cceb527a59aee8f216d6770a29cabf1c"},{"code_id":"GK_RF_2","article_number":"520","version_date":"1994-11-30","article_text":"1. Если поставщик не поставил предусмотренное договором поставки количество товаров либо не выполнил требования покупателя о замене недоброкачественных товаров или о доукомплектовании товаров в установленный срок, покупатель вправе приобрести непоставленные товары у других лиц с отнесением на поставщика всех необходимых и разумных расходов на их приобретение.\n\nИсчисление расходов покупателя на приобретение товаров у других лиц в случаях их недопоставки поставщиком или невыполнения требований покупателя об устранении недостатков товаров либо о доукомплектовании товаров производится по правилам, предусмотренным пунктом 1 статьи 524 настоящего Кодекса.\n\n2. Покупатель (получатель) вправе отказаться от оплаты товаров ненадлежащего качества и некомплектных товаров, а если такие товары оплачены, потребовать возврата уплаченных сумм впредь до устранения недостатков и доукомплектования товаров либо их замены.","article_title":"Статья 520. Права покупателя в случае недопоставки товаров, невыполнения требований об устранении недостатков товаров или о доукомплектовании товаров","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"257339e5b42f8bd61b2ec466dd758d97aa0dafe45916200efd19b9fe1abac1af"},{"code_id":"GK_RF_2","article_number":"521","version_date":"1994-11-30","article_text":"Установленная законом или договором поставки неустойка за недопоставку или просрочку поставки товаров взыскивается с поставщика до фактического исполнения обязательства в пределах его обязанности восполнить недопоставленное количество товаров в последующих периодах поставки, если иной порядок уплаты неустойки не установлен законом или договором.","article_title":"Статья 521. Неустойка за недопоставку или просрочку поставки товаров","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"703988e64d2443f9fbd92b4237a8ac9e300b35d440ca0c9403ba0a35520ff83a"},{"code_id":"GK_RF_2","article_number":"522","version_date":"1994-11-30","article_text":"1. В случаях, когда поставка одноименных товаров осуществляется поставщиком покупателю одновременно по нескольким договорам поставки и количество поставленных товаров недостаточно для погашения обязательств поставщика по всем договорам, поставленные товары должны засчитываться в счет исполнения договора, указанного поставщиком при осуществлении поставки либо без промедления после поставки.\n\n2. Если покупатель оплатил поставщику одноименные товары, полученные по нескольким договорам поставки, и суммы оплаты недостаточно для погашения обязательств покупателя по всем договорам, уплаченная сумма должна засчитываться в счет исполнения договора, указанного покупателем при осуществлении оплаты товаров или без промедления после оплаты.\n\n3. Если поставщик или покупатель не воспользовались правами, предоставленными им соответственно пунктами 1 и 2 настоящей статьи, исполнение обязательства засчитывается в погашение обязательств по договору, срок исполнения которого наступил ранее. Если срок исполнения обязательств по нескольким договорам наступил одновременно, предоставленное исполнение засчитывается пропорционально в погашение обязательств по всем договорам.","article_title":"Статья 522. Погашение однородных обязательств по нескольким договорам поставки","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9f47b6bfe6898157e01bf144ead017d353f85e044116dea4a5eae4040fabe051"},{"code_id":"GK_RF_2","article_number":"523","version_date":"1994-11-30","article_text":"1. Односторонний отказ от исполнения договора поставки (полностью или частично) или одностороннее его изменение допускаются в случае существенного нарушения договора одной из сторон (абзац четвертый пункта 2 статьи 450).\n\n2. Нарушение договора поставки поставщиком предполагается существенным в случаях:\n\nпоставки товаров ненадлежащего качества с недостатками, которые не могут быть устранены в приемлемый для покупателя срок;\n\nнеоднократного нарушения сроков поставки товаров.\n\n3. Нарушение договора поставки покупателем предполагается существенным в случаях:\n\nнеоднократного нарушения сроков оплаты товаров;\n\nнеоднократной невыборки товаров.\n\n4. Договор поставки считается измененным или расторгнутым с момента получения одной стороной уведомления другой стороны об одностороннем отказе от исполнения договора полностью или частично, если иной срок расторжения или изменения договора не предусмотрен в уведомлении либо не определен соглашением сторон.","article_title":"Статья 523. Односторонний отказ от исполнения договора поставки","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"201edf41750049a60f8ed971f3f33a9c9e5ae54dfb829f83e859cd65ded54bd3"},{"code_id":"GK_RF_2","article_number":"524","version_date":"1994-11-30","article_text":"1. Если в разумный срок после расторжения договора вследствие нарушения обязательства продавцом покупатель купил у другого лица по более высокой, но разумной цене товар взамен предусмотренного договором, покупатель может предъявить продавцу требование о возмещении убытков в виде разницы между установленной в договоре ценой и ценой по совершенной взамен сделке.\n\n2. Если в разумный срок после расторжения договора вследствие нарушения обязательства покупателем продавец продал товар другому лицу по более низкой, чем предусмотренная договором, но разумной цене, продавец может предъявить покупателю требование о возмещении убытков в виде разницы между установленной в договоре ценой и ценой по совершенной взамен сделке.\n\n3. Если после расторжения договора по основаниям, предусмотренным пунктами 1 и 2 настоящей статьи, не совершена сделка взамен расторгнутого договора и на данный товар имеется текущая цена, сторона может предъявить требование о возмещении убытков в виде разницы между ценой, установленной в договоре, и текущей ценой на момент расторжения договора.\n\nТекущей ценой признается цена, обычно взимавшаяся при сравнимых обстоятельствах за аналогичный товар в месте, где должна была быть осуществлена передача товара. Если в этом месте не существует текущей цены, может быть использована текущая цена, применявшаяся в другом месте, которое может служить разумной заменой, с учетом разницы в расходах по транспортировке товара.\n\n4. Удовлетворение требований, предусмотренных пунктами 1, 2 и 3 настоящей статьи, не освобождает сторону, не исполнившую или ненадлежаще исполнившую обязательство, от возмещения иных убытков, причиненных другой стороне, на основании статьи 15 настоящего Кодекса.\n\n(Наименование в редакции Федерального закона от 02.02.2006 № 19-ФЗ)","article_title":"Статья 524. Исчисление убытков при расторжении договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9b73b7b3bf5fb8d3c5229dc675310efe076eae20f73b4a25c3fff8562aa0729f"},{"code_id":"GK_RF_2","article_number":"525","version_date":"1994-11-30","article_text":"(Наименование в редакции Федерального закона от 02.02.2006 № 19-ФЗ)\n\nК отношениям по поставке товаров для государственных или муниципальных нужд в части, не урегулированной настоящим параграфом, применяются иные законы.  (В редакции Федерального закона от 02.02.2006 № 19-ФЗ)","article_title":"Статья 525. Основания поставки товаров для государственных или муниципальных нужд","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f15385be271ef865bf460abe408b1d06de303c3606da5d00a9a48ae76864a939"},{"code_id":"GK_RF_2","article_number":"526","version_date":"1994-11-30","article_text":"(Наименование в редакции Федерального закона от 02.02.2006 № 19-ФЗ)\n\nПо государственному или муниципальному контракту на поставку товаров для государственных или муниципальных нужд (далее - государственный или муниципальный контракт) поставщик (исполнитель) обязуется передать товары государственному или муниципальному заказчику либо по его указанию иному лицу, а государственный или муниципальный заказчик обязуется обеспечить оплату поставленных товаров. (В редакции Федерального закона от 02.02.2006 № 19-ФЗ)","article_title":"Статья 526. Государственный или муниципальный контракт на поставку товаров для государственных или муниципальных нужд","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9741bafeb3aa1217a3ce0c51bf21c93e7b5333850e493ec3c1a79bceb4787cc9"},{"code_id":"GK_RF_2","article_number":"527","version_date":"1994-11-30","article_text":"(Наименование в редакции Федерального закона от 02.02.2006 № 19-ФЗ)\n\nДля государственного или муниципального заказчика, разместившего заказ, заключение государственного или муниципального контракта является обязательным, если иное не установлено законом. (В редакции Федерального закона от 02.02.2006 № 19-ФЗ)","article_title":"Статья 527. Основания заключения государственного или муниципального контракта","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d8dd9ac9ef5aa3e4c3a64f302c80598b66d09d97d27f7ff6d334cbe599574001"},{"code_id":"GK_RF_2","article_number":"528","version_date":"1994-11-30","article_text":"(Наименование в редакции Федерального закона от 02.02.2006 № 19-ФЗ)\n\nПри отклонении протокола разногласий или истечении этого срока неурегулированные разногласия по государственному или муниципальному контракту, заключение которого является обязательным для одной из сторон, могут быть переданы другой стороной не позднее тридцати дней на рассмотрение суда. (В редакции Федерального закона от 02.02.2006 № 19-ФЗ)","article_title":"Статья 528. Порядок заключения государственного или муниципального контракта","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f44b1a96fbc55091a436ac4332dbc3b7a610500d42811784ef20f7b5e2087962"},{"code_id":"GK_RF_2","article_number":"529","version_date":"1994-11-30","article_text":"(Наименование в редакции Федерального закона от 02.02.2006 № 19-ФЗ)\n\nИзвещение о прикреплении покупателя к поставщику (исполнителю), выданное государственным или муниципальным заказчиком в соответствии с государственным или муниципальным контрактом, является основанием заключения договора поставки товаров для государственных или муниципальных нужд. (В редакции Федерального закона от 02.02.2006 № 19-ФЗ)\n\np>5. Если поставщик (исполнитель) уклоняется от заключения договора поставки товаров для государственных или муниципальных нужд, покупатель вправе обратиться в суд с требованием о понуждении поставщика (исполнителя) заключить договор на условиях разработанного покупателем проекта договора. (В редакции Федерального закона от 02.02.2006 № 19-ФЗ)","article_title":"Статья 529. Заключение договора поставки товаров для государственных или муниципальных нужд","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"eb0c83cd1aef693c3a525a4e4b723f66eee8b7cb7f5c88c494b3a9ae3bfd97e8"},{"code_id":"GK_RF_2","article_number":"530","version_date":"1994-11-30","article_text":"(Наименование в редакции Федерального закона от 02.02.2006 № 19-ФЗ)\n\n1. Покупатель вправе полностью или частично отказаться от товаров, указанных в извещении о прикреплении, и от заключения договора на их поставку.\n\nВ этом случае поставщик (исполнитель) должен незамедлительно уведомить государственного или муниципального заказчика и вправе потребовать от него извещения о прикреплении к другому покупателю. (В редакции Федерального закона от 02.02.2006 № 19-ФЗ)","article_title":"Статья 530. Отказ покупателя от заключения договора поставки товаров для государственных или муниципальных нужд","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"12483640c4edae088c1af4d9a07952e5d09d3aa1d7ddd2a57aaab6270a91f5f5"},{"code_id":"GK_RF_2","article_number":"531","version_date":"1994-11-30","article_text":"(Наименование в редакции Федерального закона от 02.02.2006 № 19-ФЗ)","article_title":"Статья 531. Исполнение государственного или муниципального контракта","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5cb468ea27c85aa81dd33aa6ad038a21d6f28d31c86f04c651bb93ff60e9de89"},{"code_id":"GK_RF_2","article_number":"532","version_date":"1994-11-30","article_text":"(Наименование в редакции Федерального закона от 02.02.2006 № 19-ФЗ)\n\nПри поставке товаров покупателям по договорам поставки товаров для государственных или муниципальных нужд оплата товаров производится покупателями по ценам, определяемым в соответствии с государственным или муниципальным контрактом, если иной порядок определения цен и расчетов не предусмотрен государственным или муниципальным контрактом. (В редакции Федерального закона от 02.02.2006 № 19-ФЗ)\n\nПри оплате покупателем товаров по договору поставки товаров для государственных или муниципальных нужд государственный или муниципальный заказчик признается поручителем по этому обязательству покупателя (статьи 361 - 367).  (В редакции Федерального закона от 02.02.2006 № 19-ФЗ)","article_title":"Статья 532. Оплата товара по договору поставки товаров для государственных или муниципальных нужд","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"97bebbf32af7d6d5c69b66281f7f0339a7988414b83687c194367ebccc15ea94"},{"code_id":"GK_RF_2","article_number":"533","version_date":"1994-11-30","article_text":"(Наименование в редакции Федерального закона от 02.02.2006 № 19-ФЗ)\n\nУбытки, причиненные покупателю таким отказом поставщика, возмещаются государственным или муниципальным заказчиком. (В редакции Федерального закона от 02.02.2006 № 19-ФЗ)","article_title":"Статья 533. Возмещение убытков, причиненных в связи с выполнением или расторжением государственного или муниципального контракта","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"33d7716c87df2bfdf666bdd01deb8cb96374e5624d0890c1985d8c9fabdf520a"},{"code_id":"GK_RF_2","article_number":"534","version_date":"1994-11-30","article_text":"(Наименование в редакции Федерального закона от 02.02.2006 № 19-ФЗ)\n\nВ случаях, предусмотренных законом, государственный или муниципальный заказчик вправе полностью или частично отказаться от товаров, поставка которых предусмотрена государственным или муниципальным контрактом, при условии возмещения поставщику убытков, причиненных таким отказом. (В редакции Федерального закона от 02.02.2006 № 19-ФЗ)\n\nЕсли отказ государственного или муниципального заказчика от товаров, поставка которых предусмотрена государственным или муниципальным контрактом, повлек расторжение или изменение договора поставки товаров для государственных или муниципальных нужд, убытки, причиненные покупателю таким расторжением или изменением, возмещаются государственным или муниципальным заказчиком. (В редакции Федерального закона от 02.02.2006 № 19-ФЗ)","article_title":"Статья 534. Отказ государственного или муниципального заказчика от товаров, поставленных по государственному или муниципальному контракту","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"593611e2b0095c0722c5690f7f6fa1a212c50c3ec941f9f76f321e07be45e404"},{"code_id":"GK_RF_2","article_number":"535","version_date":"1994-11-30","article_text":"1. По договору контрактации производитель сельскохозяйственной продукции обязуется передать выращенную (произведенную) им сельскохозяйственную продукцию заготовителю - лицу, осуществляющему закупки такой продукции для переработки или продажи.\n\n2. К отношениям по договору контрактации, не урегулированным правилами настоящего параграфа, применяются правила о договоре поставки (статьи 506 - 524), а в соответствующих случаях о поставке товаров для государственных нужд (статьи 525 - 534).","article_title":"Статья 535. Договор контрактации","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"be8c639944af272cc719a1c0b768f150ea61047a64125cd937a798a55f5d13a4"},{"code_id":"GK_RF_2","article_number":"536","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено договором контрактации, заготовитель обязан принять сельскохозяйственную продукцию у производителя по месту ее нахождения и обеспечить ее вывоз.\n\n2. В случае, когда принятие сельскохозяйственной продукции осуществляется в месте нахождения заготовителя или ином указанном им месте, заготовитель не вправе отказаться от принятия сельскохозяйственной продукции, соответствующей условиям договора контрактации и переданной заготовителю в обусловленный договором срок.\n\n3. Договором контрактации может быть предусмотрена обязанность заготовителя, осуществляющего переработку сельскохозяйственной продукции, возвращать производителю по его требованию отходы от переработки сельскохозяйственной продукции с оплатой по цене, определенной договором.","article_title":"Статья 536. Обязанности заготовителя","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c84579a174a11ef1e6cc07801b9961d794e4d15cb30800e1f27902b07454376f"},{"code_id":"GK_RF_2","article_number":"537","version_date":"1994-11-30","article_text":"Производитель сельскохозяйственной продукции обязан передать заготовителю выращенную (произведенную) сельскохозяйственную продукцию в количестве и ассортименте, предусмотренных договором контрактации.","article_title":"Статья 537. Обязанности производителя сельскохозяйственной продукции","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a3356f8bcb961595c073ed89c18dab6aceaf5bf63e67eabea49e48c9be21fbf1"},{"code_id":"GK_RF_2","article_number":"538","version_date":"1994-11-30","article_text":"Производитель сельскохозяйственной продукции, не исполнивший обязательство либо ненадлежащим образом исполнивший обязательство, несет ответственность при наличии его вины.","article_title":"Статья 538. Ответственность производителя сельскохозяйственной продукции","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4c087f8087938c276b14df793da8f7f1d0b0b413563b1ce736ec1d599a4c914b"},{"code_id":"GK_RF_2","article_number":"539","version_date":"1994-11-30","article_text":"1. По договору энергоснабжения энергоснабжающая организация обязуется подавать абоненту (потребителю) через присоединенную сеть энергию, а абонент обязуется оплачивать принятую энергию, а также соблюдать предусмотренный договором режим ее потребления, обеспечивать безопасность эксплуатации находящихся в его ведении энергетических сетей и исправность используемых им приборов и оборудования, связанных с потреблением энергии.\n\n2. Договор энергоснабжения заключается с абонентом при наличии у него отвечающего установленным техническим требованиям энергопринимающего устройства, присоединенного к сетям энергоснабжающей организации, и другого необходимого оборудования, а также при обеспечении учета потребления энергии.\n\n3. К отношениям по договору энергоснабжения, не урегулированным настоящим Кодексом, применяются законы и иные правовые акты об энергоснабжении, а также обязательные правила, принятые в соответствии с ними.","article_title":"Статья 539. Договор энергоснабжения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3d1f23b55f3d58b2b3bd493f4b4350a121dcb8dcb8f0fd3a311ed4b34a189b6d"},{"code_id":"GK_RF_2","article_number":"540","version_date":"1994-11-30","article_text":"1. В случае, когда абонентом по договору энергоснабжения выступает гражданин, использующий энергию для бытового потребления, договор считается заключенным с момента первого фактического подключения абонента в установленном порядке к присоединенной сети.\n\nЕсли иное не предусмотрено соглашением сторон, такой договор считается заключенным на неопределенный срок и может быть изменен или расторгнут по основаниям, предусмотренным статьей 546 настоящего Кодекса.\n\n2. Договор энергоснабжения, заключенный на определенный срок, считается продленным на тот же срок и на тех же условиях, если до окончания срока его действия ни одна из сторон не заявит о его прекращении или изменении либо о заключении нового договора.\n\n3. Если одной из сторон до окончания срока действия договора внесено предложение о заключении нового договора, то отношения сторон до заключения нового договора регулируются ранее заключенным договором.","article_title":"Статья 540. Заключение и продление договора энергоснабжения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f3a0ccf10e2a4bd0b265015e6abe247a5e89fb1b7ccd5bb639cd2855e2702b03"},{"code_id":"GK_RF_2","article_number":"543","version_date":"1994-11-30","article_text":"1. Абонент обязан обеспечивать надлежащее техническое состояние и безопасность эксплуатируемых энергетических сетей, приборов и оборудования, соблюдать установленный режим потребления энергии, а также немедленно сообщать энергоснабжающей организации об авариях, о пожарах, неисправностях приборов учета энергии и об иных нарушениях, возникающих при пользовании энергией.\n\n2. В случае, когда абонентом по договору энергоснабжения выступает гражданин, использующий энергию для бытового потребления, обязанность обеспечивать надлежащее техническое состояние и безопасность энергетических сетей, а также приборов учета потребления энергии возлагается на энергоснабжающую организацию, если иное не установлено законом или иными правовыми актами.\n\n3. Требования к техническому состоянию и эксплуатации энергетических сетей, приборов и оборудования, а также порядок осуществления контроля за их соблюдением определяются законом, иными правовыми актами и принятыми в соответствии с ними обязательными правилами.","article_title":"Статья 543. Обязанности покупателя по содержанию и эксплуатации сетей, приборов и оборудования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a8d6b4cdfe66bd311d27771e09d3197f68d6a0e189d06d45a4aecff43f1f2b8a"},{"code_id":"GK_RF_2","article_number":"544","version_date":"1994-11-30","article_text":"1. Оплата энергии производится за фактически принятое абонентом количество энергии в соответствии с данными учета энергии, если иное не предусмотрено законом, иными правовыми актами или соглашением сторон.\n\n2. Порядок расчетов за энергию определяется законом, иными правовыми актами или соглашением сторон.","article_title":"Статья 544. Оплата энергии","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7da037f9e679ddc885ceb12e1488d4193fad699275fab7532a9cc9615566a7dd"},{"code_id":"GK_RF_2","article_number":"545","version_date":"1994-11-30","article_text":"Абонент может передавать энергию, принятую им от энергоснабжающей организации через присоединенную сеть, другому лицу (субабоненту) только с согласия энергоснабжающей организации.","article_title":"Статья 545. Субабонент","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a3e8e6299f6c32bb50bef18aae79370c211ff7e2aacc5af6a9e9665b3e23f4f5"},{"code_id":"GK_RF_2","article_number":"546","version_date":"1994-11-30","article_text":"1. В случае, когда абонентом по договору энергоснабжения выступает гражданин, использующий энергию для бытового потребления, он вправе расторгнуть договор в одностороннем порядке при условии уведомления об этом энергоснабжающей организации и полной оплаты использованной энергии.\n\nВ случае, когда абонентом по договору энергоснабжения выступает юридическое лицо, энергоснабжающая организация вправе отказаться от исполнения договора в одностороннем порядке по основаниям, предусмотренным статьей 523 настоящего Кодекса, за исключением случаев, установленных законом или иными правовыми актами.\n\n2. Перерыв в подаче, прекращение или ограничение подачи энергии допускаются по соглашению сторон, за исключением случаев, когда удостоверенное органом государственного энергетического надзора неудовлетворительное состояние энергетических установок абонента угрожает аварией или создает угрозу жизни и безопасности граждан. О перерыве в подаче, прекращении или об ограничении подачи энергии энергоснабжающая организация должна предупредить абонента.\n\nПрекращение или ограничение подачи энергии без согласования с абонентом - юридическим лицом, но с соответствующим его предупреждением допускается в установленном законом или иными правовыми актами порядке в случае нарушения указанным абонентом обязательств по оплате энергии. (Дополнение абзацем - Федеральный закон от 26.03.2003 № 37-ФЗ)","article_title":"Статья 546. Изменение и расторжение договора энергоснабжения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"74ff7f3c1bed99145edffba8e2575737cbc26c346efc42a00b84b33dc737ff25"},{"code_id":"GK_RF_2","article_number":"547","version_date":"1994-11-30","article_text":"1. В случаях неисполнения или ненадлежащего исполнения обязательств по договору энергоснабжения сторона, нарушившая обязательство, обязана возместить причиненный этим реальный ущерб (пункт 2 статьи 15).\n\n2. Если в результате регулирования режима потребления энергии, осуществленного на основании закона или иных правовых актов, допущен перерыв в подаче энергии абоненту, энергоснабжающая организация несет ответственность за неисполнение или ненадлежащее исполнение договорных обязательств при наличии ее вины.","article_title":"Статья 547. Ответственность по договору энергоснабжения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"794d6bbb632135c2ca57d36cbde67649516646e6d194e706bc63f65c15748963"},{"code_id":"GK_RF_2","article_number":"548","version_date":"1994-11-30","article_text":"1. Правила, предусмотренные статьями 539 - 547 настоящего Кодекса, применяются к отношениям, связанным со снабжением тепловой энергией через присоединенную сеть, если иное не установлено законом или иными правовыми актами.\n\n2. К отношениям, связанным со снабжением через присоединенную сеть газом, нефтью и нефтепродуктами, водой и другими товарами, правила о договоре энергоснабжения (статьи 539 - 547) применяются, если иное не установлено законом, иными правовыми актами или не вытекает из существа обязательства.","article_title":"Статья 548. Применение правил об энергоснабжении к иным договорам","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fbc8c530190d6c7f78d05eb16d4d32162ee6dd9f7c9cb64cdf2e9f6c2bcdde43"},{"code_id":"GK_RF_2","article_number":"549","version_date":"1994-11-30","article_text":"1. По договору купли-продажи недвижимого имущества (договору продажи недвижимости) продавец обязуется передать в собственность покупателя земельный участок, здание, сооружение, квартиру или другое недвижимое имущество (статья 130).\n\n2. Правила, предусмотренные настоящим параграфом, применяются к продаже предприятий постольку, поскольку иное не предусмотрено правилами о договоре продажи предприятия (статьи 559 - 566).","article_title":"Статья 549. Договор продажи недвижимости","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"dde5f443cdfcb784b2a319f4fc7e1b7975facbe656914971bf6bd64e6de2c7d3"},{"code_id":"GK_RF_2","article_number":"550","version_date":"1994-11-30","article_text":"Договор продажи недвижимости заключается в письменной форме путем составления одного документа, подписанного сторонами (пункт 2 статьи 434).\n\nНесоблюдение формы договора продажи недвижимости влечет его недействительность.","article_title":"Статья 550. Форма договора продажи недвижимости","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"db9901c9a74267823db9baf8a0456340da8d4ab701a4b0430fa25b1bda736501"},{"code_id":"GK_RF_2","article_number":"551","version_date":"1994-11-30","article_text":"1. Переход права собственности на недвижимость по договору продажи недвижимости к покупателю подлежит государственной регистрации.\n\n2. Исполнение договора продажи недвижимости сторонами до государственной регистрации перехода права собственности не является основанием для изменения их отношений с третьими лицами.","article_title":"Статья 551. Государственная регистрация перехода права собственности на недвижимость","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b840f6e3a807808d8b4db48722d6fb381c46ae694abc2522acd7002c0203c3ad"},{"code_id":"GK_RF_2","article_number":"552","version_date":"1994-11-30","article_text":"Абзац. (Утратил силу - Федеральный закон от 26.06.2007 № 118-ФЗ)\n\nа этого участка, если это не противоречит условиям пользования таким участком, установленным законом или договором.\n\nПри продаже такой недвижимости покупатель приобретает право пользования соответствующим земельным участком на тех же условиях, что и продавец недвижимости.  (В редакции Федерального закона от 26.06.2007 № 118-ФЗ)","article_title":"Статья 552. Права на земельный участок при продаже здания, сооружения или другой находящейся на нем недвижимости","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c729d11b5b07513d2d07b3abe760b79c69005afc4bfa5f5cc8bc0f9f8eae6efc"},{"code_id":"GK_RF_2","article_number":"553","version_date":"1994-11-30","article_text":"(Статья утратила силу - Федеральный закон от 26.06.2007 № 118-ФЗ)","article_title":"Статья 553. .","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"375e24ef5d86c8a0dc55e047c79a07b14bef972d3f5aeb2e99a0b14ed3058876"},{"code_id":"GK_RF_2","article_number":"554","version_date":"1994-11-30","article_text":"В договоре продажи недвижимости должны быть указаны данные, позволяющие определенно установить недвижимое имущество, подлежащее передаче покупателю по договору, в том числе данные, определяющие расположение недвижимости на соответствующем земельном участке либо в составе другого недвижимого имущества.\n\nПри отсутствии этих данных в договоре условие о недвижимом имуществе, подлежащем передаче, считается не согласованным сторонами, а соответствующий договор не считается заключенным.","article_title":"Статья 554. Определение предмета в договоре продажи недвижимости","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d76f5b1f0e2deb760d1c909a9295ffac55ccabdceeb02bfa12af6d7b4c57b3fe"},{"code_id":"GK_RF_2","article_number":"555","version_date":"1994-11-30","article_text":"1. Договор продажи недвижимости должен предусматривать цену этого имущества.\n\nПри отсутствии в договоре согласованного сторонами в письменной форме условия о цене недвижимости договор о ее продаже считается незаключенным. При этом правила определения цены, предусмотренные пунктом 3 статьи 424 настоящего Кодекса, не применяются.\n\n2. Если иное не предусмотрено законом или договором продажи недвижимости, установленная в нем цена здания, сооружения или другого недвижимого имущества, находящегося на земельном участке, включает цену передаваемой с этим недвижимым имуществом соответствующей части земельного участка или права на нее.\n\n3. В случаях, когда цена недвижимости в договоре продажи недвижимости установлена на единицу ее площади или иного показателя ее размера, общая цена такого недвижимого имущества, подлежащая уплате, определяется исходя из фактического размера переданного покупателю недвижимого имущества.","article_title":"Статья 555. Цена в договоре продажи недвижимости","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"45d3d3e4e69eb81250273d5491fa6c7650ad077055f5ac80e4f00eac26d19352"},{"code_id":"GK_RF_2","article_number":"556","version_date":"1994-11-30","article_text":"1. Передача недвижимости продавцом и принятие ее покупателем осуществляются по подписываемому сторонами передаточному акту или иному документу о передаче.\n\nЕсли иное не предусмотрено законом или договором, обязательство продавца передать недвижимость покупателю считается исполненным после вручения этого имущества покупателю и подписания сторонами соответствующего документа о передаче.\n\nУклонение одной из сторон от подписания документа о передаче недвижимости на условиях, предусмотренных договором, считается отказом соответственно продавца от исполнения обязанности передать имущество, а покупателя - обязанности принять имущество.\n\n2. Принятие покупателем недвижимости, не соответствующей условиям договора продажи недвижимости, в том числе в случае, когда такое несоответствие оговорено в документе о передаче недвижимости, не является основанием для освобождения продавца от ответственности за ненадлежащее исполнение договора.","article_title":"Статья 556. Передача недвижимости","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7b18a23b13195c9a8f598b76fc5cebfaf98b9fd37f66b99ca90b0d44e84ce03b"},{"code_id":"GK_RF_2","article_number":"557","version_date":"1994-11-30","article_text":"В случае передачи продавцом покупателю недвижимости, не соответствующей условиям договора продажи недвижимости о ее качестве, применяются правила статьи 475 настоящего Кодекса, за исключением положений о праве покупателя потребовать замены товара ненадлежащего качества на товар, соответствующий договору.","article_title":"Статья 557. Последствия передачи недвижимости ненадлежащего качества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"83deaa7b1a7bb2cd18bc975885446ab8cb5fc9e8866495ae371b7c72faada0a7"},{"code_id":"GK_RF_2","article_number":"558","version_date":"1994-11-30","article_text":"1. Существенным условием договора продажи жилого дома, квартиры, части жилого дома или квартиры, в которых проживают лица, сохраняющие в соответствии с законом право пользования этим жилым помещением после его приобретения покупателем, является перечень этих лиц с указанием их прав на пользование продаваемым жилым помещением.\n\n2. Договор продажи жилого дома, квартиры, части жилого дома или квартиры подлежит государственной регистрации и считается заключенным с момента такой регистрации.","article_title":"Статья 558. Особенности продажи жилых помещений","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f54a52d2352656c568bde3bf86699e24355d1c62ea235e29d830830a004f6c8c"},{"code_id":"GK_RF_2","article_number":"559","version_date":"1994-11-30","article_text":"1. По договору продажи предприятия продавец обязуется передать в собственность покупателя предприятие в целом как имущественный комплекс (статья 132), за исключением прав и обязанностей, которые продавец не вправе передавать другим лицам.","article_title":"Статья 559. Договор продажи предприятия","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8150eb163184730a3798bea339e0408ecec60fcd9dc651f680047261281f7ac1"},{"code_id":"GK_RF_2","article_number":"560","version_date":"1994-11-30","article_text":"1. Договор продажи предприятия заключается в письменной форме путем составления одного документа, подписанного сторонами (пункт 2 статьи 434), с обязательным приложением к нему документов, указанных в пункте 2 статьи 561 настоящего Кодекса.\n\n2. Несоблюдение формы договора продажи предприятия влечет его недействительность.\n\n3. Договор продажи предприятия подлежит государственной регистрации и считается заключенным с момента такой регистрации.","article_title":"Статья 560. Форма и государственная регистрация договора продажи предприятия","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0e68e8742a5a2ea1a2594d1058bbfb7c37cac914fcd647795f0a1516185a00f7"},{"code_id":"GK_RF_2","article_number":"561","version_date":"1994-11-30","article_text":"1. Состав и стоимость продаваемого предприятия определяются в договоре продажи предприятия на основе полной инвентаризации предприятия, проводимой в соответствии с установленными правилами такой инвентаризации.\n\n2. До подписания договора продажи предприятия должны быть составлены и рассмотрены сторонами: акт инвентаризации, бухгалтерский баланс, заключение независимого аудитора о составе и стоимости предприятия, а также перечень всех долгов (обязательств), включаемых в состав предприятия, с указанием кредиторов, характера, размера и сроков их требований.\n\nИмущество, права и обязанности, указанные в названных документах, подлежат передаче продавцом покупателю, если иное не следует из правил статьи 559 настоящего Кодекса и не установлено соглашением сторон.","article_title":"Статья 561. Удостоверение состава продаваемого предприятия","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c32fe3757042fbbc26bfe3ca9218383b9b7481490ef863fff779d9a03eedf6c5"},{"code_id":"GK_RF_2","article_number":"562","version_date":"1994-11-30","article_text":"1. Кредиторы по обязательствам, включенным в состав продаваемого предприятия, должны быть до его передачи покупателю письменно уведомлены о его продаже одной из сторон договора продажи предприятия.\n\n2. Кредитор, который письменно не сообщил продавцу или покупателю о своем согласии на перевод долга, вправе в течение трех месяцев со дня получения уведомления о продаже предприятия потребовать либо прекращения или досрочного исполнения обязательства и возмещения продавцом причиненных этим убытков, либо признания договора продажи предприятия недействительным полностью или в соответствующей части.\n\n3. Кредитор, который не был уведомлен о продаже предприятия в порядке, предусмотренном пунктом 1 настоящей статьи, может предъявить иск об удовлетворении требований, предусмотренных пунктом 2 настоящей статьи, в течение года со дня, когда он узнал или должен был узнать о передаче предприятия продавцом покупателю.\n\n4. После передачи предприятия покупателю продавец и покупатель несут солидарную ответственность по включенным в состав переданного предприятия долгам, которые были переведены на покупателя без согласия кредитора.","article_title":"Статья 562. Права кредиторов при продаже предприятия","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"488115b601041da56c88edae87386db48c250460bb507a0499566db71829ea5e"},{"code_id":"GK_RF_2","article_number":"563","version_date":"1994-11-30","article_text":"1. Передача предприятия продавцом покупателю осуществляется по передаточному акту, в котором указываются данные о составе предприятия и об уведомлении кредиторов о продаже предприятия, а также сведения о выявленных недостатках переданного имущества и перечень имущества, обязанности по передаче которого не исполнены продавцом ввиду его утраты.\n\nПодготовка предприятия к передаче, включая составление и представление на подписание передаточного акта, является обязанностью продавца и осуществляется за его счет, если иное не предусмотрено договором.\n\n2. Предприятие считается переданным покупателю со дня подписания передаточного акта обеими сторонами.\n\nС этого момента на покупателя переходит риск случайной гибели или случайного повреждения имущества, переданного в составе предприятия.","article_title":"Статья 563. Передача предприятия","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d77f6d63c5a2e078230f18c3f319b87efc2249ab880aa88256e87a13ab62e913"},{"code_id":"GK_RF_2","article_number":"564","version_date":"1994-11-30","article_text":"1. Право собственности на предприятие переходит к покупателю с момента государственной регистрации этого права.\n\n2. Если иное не предусмотрено договором продажи предприятия, право собственности на предприятие переходит к покупателю и подлежит государственной регистрации непосредственно после передачи предприятия покупателю (статья 563).\n\n3. В случаях, когда договором предусмотрено сохранение за продавцом права собственности на предприятие, переданное покупателю, до оплаты предприятия или до наступления иных обстоятельств, покупатель вправе до перехода к нему права собственности распоряжаться имуществом и правами, входящими в состав переданного предприятия, в той мере, в какой это необходимо для целей, для которых предприятие было приобретено.","article_title":"Статья 564. Переход права собственности на предприятие","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f40023351ec0550b01d8f4a97b4f094ff779b6d0f9ac4cd3937a1e652ac0e3e0"},{"code_id":"GK_RF_2","article_number":"565","version_date":"1994-11-30","article_text":"1. Последствия передачи продавцом и принятия покупателем по передаточному акту предприятия, состав которого не соответствует предусмотренному договором продажи предприятия, в том числе в отношении качества переданного имущества, определяются на основании правил, предусмотренных статьями 460 - 462, 466, 469, 475, 479 настоящего Кодекса, если иное не вытекает из договора и не предусмотрено пунктами 2 - 4 настоящей статьи.\n\n2. В случае, когда предприятие передано и принято по передаточному акту, в котором указаны сведения о выявленных недостатках предприятия и об утраченном имуществе (пункт 1 статьи 563), покупатель вправе требовать соответствующего уменьшения покупной цены предприятия, если право на предъявление в таких случаях иных требований не предусмотрено договором продажи предприятия.\n\n3. Покупатель вправе требовать уменьшения покупной цены в случае передачи ему в составе предприятия долгов (обязательств) продавца, которые не были указаны в договоре продажи предприятия или передаточном акте, если продавец не докажет, что покупатель знал о таких долгах (обязательствах) во время заключения договора и передачи предприятия.\n\n4. Продавец в случае получения уведомления покупателя о недостатках имущества, переданного в составе предприятия, или отсутствия в этом составе отдельных видов имущества, подлежащих передаче, может без промедления заменить имущество ненадлежащего качества или предоставить покупателю недостающее имущество.\n\n5. Покупатель вправе в судебном порядке требовать расторжения или изменения договора продажи предприятия и возвращения того, что исполнено сторонами по договору, если установлено, что предприятие ввиду недостатков, за которые продавец отвечает, не пригодно для целей, названных в договоре продажи, и эти недостатки не устранены продавцом на условиях, в порядке и в сроки, которые установлены в соответствии с настоящим Кодексом, другими законами, иными правовыми актами или договором, либо устранение таких недостатков невозможно.","article_title":"Статья 565. Последствия передачи и принятия предприятия с недостатками","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"79bc73534447e8722a6500273bd3da349f143780c155fcb91e05845e07800603"},{"code_id":"GK_RF_2","article_number":"566","version_date":"1994-11-30","article_text":"Правила настоящего Кодекса о последствиях недействительности сделок и об изменении или о расторжении договора купли-продажи, предусматривающие возврат или взыскание в натуре полученного по договору с одной стороны или с обеих сторон, применяются к договору продажи предприятия, если такие последствия существенно не нарушают права и охраняемые законом интересы кредиторов продавца и покупателя, других лиц и не противоречат общественным интересам.","article_title":"Статья 566. Применение к договору продажи предприятия правил о последствиях недействительности сделок и об изменении или о расторжении договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"17bfa88f5e348049400b313602acadf12c2df8f08e14ca5515b85decbadeb096"},{"code_id":"GK_RF_2","article_number":"567","version_date":"1994-11-30","article_text":"1. По договору мены каждая из сторон обязуется передать в собственность другой стороны один товар в обмен на другой.\n\n2. К договору мены применяются соответственно правила о купле-продаже (глава 30), если это не противоречит правилам настоящей главы и существу мены. При этом каждая из сторон признается продавцом товара, который она обязуется передать, и покупателем товара, который она обязуется принять в обмен.","article_title":"Статья 567. Договор мены","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c180cc3a627775e41fb37b4d4b89e740da320dd443584a2adc6dc59e14028ca5"},{"code_id":"GK_RF_2","article_number":"568","version_date":"1994-11-30","article_text":"1. Если из договора мены не вытекает иное, товары, подлежащие обмену, предполагаются равноценными, а расходы на их передачу и принятие осуществляются в каждом случае той стороной, которая несет соответствующие обязанности.\n\n2. В случае, когда в соответствии с договором мены обмениваемые товары признаются неравноценными, сторона, обязанная передать товар, цена которого ниже цены товара, предоставляемого в обмен, должна оплатить разницу в ценах непосредственно до или после исполнения ее обязанности передать товар, если иной порядок оплаты не предусмотрен договором.","article_title":"Статья 568. Цены и расходы по договору мены","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e351bf602d89fdedf68f54699b5bdba3608ef20172190ec303e073187bcb349b"},{"code_id":"GK_RF_2","article_number":"569","version_date":"1994-11-30","article_text":"В случае, когда в соответствии с договором мены сроки передачи обмениваемых товаров не совпадают, к исполнению обязательства передать товар стороной, которая должна передать товар после передачи товара другой стороной, применяются правила о встречном исполнении обязательств (статья 328).","article_title":"Статья 569. Встречное исполнение обязательства передать товар по договору мены","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9d042e48b3865cbfefc1a5b941d32267260c12dda1e3127433c811c266f6a99e"},{"code_id":"GK_RF_2","article_number":"570","version_date":"1994-11-30","article_text":"Если законом или договором мены не предусмотрено иное, право собственности на обмениваемые товары переходит к сторонам, выступающим по договору мены в качестве покупателей, одновременно после исполнения обязательств передать соответствующие товары обеими сторонами.","article_title":"Статья 570. Переход права собственности на обмениваемые товары","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d1f17092f6c313a2f1399f938ff1a4226fb3d51e87e136a7dba691e26ef3fdb2"},{"code_id":"GK_RF_2","article_number":"571","version_date":"1994-11-30","article_text":"Сторона, у которой третьим лицом изъят товар, приобретенный по договору мены, вправе при наличии оснований, предусмотренных статьей 461 настоящего Кодекса, потребовать от другой стороны возврата товара, полученного последней в обмен, и (или) возмещения убытков.","article_title":"Статья 571. Ответственность за изъятие товара, приобретенного по договору мены","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e7d6c80a8675ad34ce74212f1850defa61905adfad507644e379cb2a862bf627"},{"code_id":"GK_RF_2","article_number":"572","version_date":"1994-11-30","article_text":"1. По договору дарения одна сторона (даритель) безвозмездно передает или обязуется передать другой стороне (одаряемому) вещь в собственность либо имущественное право (требование) к себе или к третьему лицу либо освобождает или обязуется освободить ее от имущественной обязанности перед собой или перед третьим лицом.\n\nПри наличии встречной передачи вещи или права либо встречного обязательства договор не признается дарением. К такому договору применяются правила, предусмотренные пунктом 2 статьи 170 настоящего Кодекса.\n\n2. Обещание безвозмездно передать кому-либо вещь или имущественное право либо освободить кого-либо от имущественной обязанности (обещание дарения) признается договором дарения и связывает обещавшего, если обещание сделано в надлежащей форме (пункт 2 статьи 574) и содержит ясно выраженное намерение совершить в будущем безвозмездную передачу вещи или права конкретному лицу либо освободить его от имущественной обязанности.\n\nОбещание подарить все свое имущество или часть всего своего имущества без указания на конкретный предмет дарения в виде вещи, права или освобождения от обязанности ничтожно.\n\n3. Договор, предусматривающий передачу дара одаряемому после смерти дарителя, ничтожен.\n\nК такого рода дарению применяются правила гражданского законодательства о наследовании.","article_title":"Статья 572. Договор дарения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"63d488bc18f9d7cca3380377102d2d85be2fd7ce404f1ea9fa40fc1365326b7c"},{"code_id":"GK_RF_2","article_number":"573","version_date":"1994-11-30","article_text":"1. Одаряемый вправе в любое время до передачи ему дара от него отказаться. В этом случае договор дарения считается расторгнутым.\n\n2. Если договор дарения заключен в письменной форме, отказ от дара должен быть совершен также в письменной форме. В случае, когда договор дарения зарегистрирован (пункт 3 статьи 574), отказ от принятия дара также подлежит государственной регистрации.\n\n3. Если договор дарения был заключен в письменной форме, даритель вправе требовать от одаряемого возмещения реального ущерба, причиненного отказом принять дар.","article_title":"Статья 573. Отказ одаряемого принять дар","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b7356129bdfb6bea7290eb1723261cb6d44bcbf0623501ea9a3cff77d7d0a3f4"},{"code_id":"GK_RF_2","article_number":"574","version_date":"1994-11-30","article_text":"1. Дарение, сопровождаемое передачей дара одаряемому, может быть совершено устно, за исключением случаев, предусмотренных пунктами 2 и 3 настоящей статьи.\n\nПередача дара осуществляется посредством его вручения, символической передачи (вручение ключей и т.п.) либо вручения правоустанавливающих документов.\n\n2. Договор дарения движимого имущества должен быть совершен в письменной форме в случаях, когда:\n\nдарителем является юридическое лицо и стоимость дара превышает три тысячи рублей; (В редакции Федерального закона от 25.12.2008 № 280-ФЗ)\n\nдоговор содержит обещание дарения в будущем.\n\nВ случаях, предусмотренных в настоящем пункте, договор дарения, совершенный устно, ничтожен.","article_title":"Статья 574. Форма договора дарения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c52b1627ffa5f06715c23751220ccdee3fb87aee0591c2464a1fb3f6dec4e3c0"},{"code_id":"GK_RF_2","article_number":"575","version_date":"1994-11-30","article_text":"1) от имени малолетних и граждан, признанных недееспособными, их законными представителями;\n\n2) работникам образовательных организаций, медицинских организаций, организаций, оказывающих социальные услуги, и аналогичных организаций, в том числе организаций для детей-сирот и детей, оставшихся без попечения родителей, гражданами, находящимися в них на лечении, содержании или воспитании, супругами и родственниками этих граждан; (В редакции Федерального закона от 24.04.2008 № 49-ФЗ)\n\n3) лицам, замещающим государственные должности Российской Федерации, государственные должности субъектов Российской Федерации, муниципальные должности, государственным служащим, муниципальным служащим, служащим Банка России в связи с их должностным положением или в связи с исполнением ими служебных обязанностей; (В редакции Федерального закона от 25.12.2008 № 280-ФЗ)\n\n4) в отношениях между коммерческими организациями.","article_title":"Статья 575. Запрещение дарения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7a96c42732446eb25b4f91a5c5f26153f2aeaa148a7f9fd9e1cfb30060e68851"},{"code_id":"GK_RF_2","article_number":"576","version_date":"1994-11-30","article_text":"1. Юридическое лицо, которому вещь принадлежит на праве хозяйственного ведения или оперативного управления, вправе подарить ее с согласия собственника, если законом не предусмотрено иное. Это ограничение не распространяется на обычные подарки небольшой стоимости.\n\n2. Дарение имущества, находящегося в общей совместной собственности, допускается по согласию всех участников совместной собственности с соблюдением правил, предусмотренных статьей 253 настоящего Кодекса.\n\n3. Дарение принадлежащего дарителю права требования к третьему лицу осуществляется с соблюдением правил, предусмотренных статьями 382 - 386, 388 и 389 настоящего Кодекса.\n\n4. Дарение посредством исполнения за одаряемого его обязанности перед третьим лицом осуществляется с соблюдением правил, предусмотренных пунктом 1 статьи 313 настоящего Кодекса.\n\nДарение посредством перевода дарителем на себя долга одаряемого перед третьим лицом осуществляется с соблюдением правил, предусмотренных статьями 391 и 392 настоящего Кодекса.\n\n5. Доверенность на совершение дарения представителем, в которой не назван одаряемый и не указан предмет дарения, ничтожна.","article_title":"Статья 576. Ограничения дарения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f75bc197b243b4eadbf0ce145642a0f58442936e7176e02c1fc79a9c73d6f1c6"},{"code_id":"GK_RF_2","article_number":"577","version_date":"1994-11-30","article_text":"1. Даритель вправе отказаться от исполнения договора, содержащего обещание передать в будущем одаряемому вещь или право либо освободить одаряемого от имущественной обязанности, если после заключения договора имущественное или семейное положение либо состояние здоровья дарителя изменилось настолько, что исполнение договора в новых условиях приведет к существенному снижению уровня его жизни.\n\n2. Даритель вправе отказаться от исполнения договора, содержащего обещание передать в будущем одаряемому вещь или право либо освободить одаряемого от имущественной обязанности, по основаниям, дающим ему право отменить дарение (пункт 1 статьи 578).\n\n3. Отказ дарителя от исполнения договора дарения по основаниям, предусмотренным пунктами 1 и 2 настоящей статьи, не дает одаряемому права требовать возмещения убытков.","article_title":"Статья 577. Отказ от исполнения договора дарения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f60676581fae3fb8364080f0fb31273bbe5235b25c4099063e009ac02c68f7c8"},{"code_id":"GK_RF_2","article_number":"578","version_date":"1994-11-30","article_text":"1. Даритель вправе отменить дарение, если одаряемый совершил покушение на его жизнь, жизнь кого-либо из членов его семьи или близких родственников либо умышленно причинил дарителю телесные повреждения.\n\nВ случае умышленного лишения жизни дарителя одаряемым право требовать в суде отмены дарения принадлежит наследникам дарителя.\n\n2. Даритель вправе потребовать в судебном порядке отмены дарения, если обращение одаряемого с подаренной вещью, представляющей для дарителя большую неимущественную ценность, создает угрозу ее безвозвратной утраты.\n\n3. По требованию заинтересованного лица суд может отменить дарение, совершенное индивидуальным предпринимателем или юридическим лицом в нарушение положений закона о несостоятельности (банкротстве) за счет средств, связанных с его предпринимательской деятельностью, в течение шести месяцев, предшествовавших объявлению такого лица несостоятельным (банкротом).\n\n4. В договоре дарения может быть обусловлено право дарителя отменить дарение в случае, если он переживет одаряемого.\n\n5. В случае отмены дарения одаряемый обязан возвратить подаренную вещь, если она сохранилась в натуре к моменту отмены дарения.","article_title":"Статья 578. Отмена дарения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3c774cf902f5a939cc528a391f8dbbd6055f45db3c2073807f954450f2481917"},{"code_id":"GK_RF_2","article_number":"579","version_date":"1994-11-30","article_text":"Правила об отказе от исполнения договора дарения (статья 577) и об отмене дарения (статья 578) не применяются к обычным подаркам небольшой стоимости.","article_title":"Статья 579. Случаи, в которых отказ от исполнения договора дарения и отмена дарения невозможны","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"859e7bf17c6d3c4cc662df754ec0a6ecef15b78824369af8bee0107fd570d445"},{"code_id":"GK_RF_2","article_number":"580","version_date":"1994-11-30","article_text":"Вред, причиненный жизни, здоровью или имуществу одаряемого гражданина вследствие недостатков подаренной вещи, подлежит возмещению дарителем в соответствии с правилами, предусмотренными главой 59 настоящего Кодекса, если доказано, что эти недостатки возникли до передачи вещи одаряемому, не относятся к числу явных и даритель, хотя и знал о них, не предупредил о них одаряемого.","article_title":"Статья 580. Последствия причинения вреда вследствие недостатков подаренной вещи","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8b24be835d1bd9278983ff27ab68e221f855b8066a99bbde492dee5b41ec09c0"},{"code_id":"GK_RF_2","article_number":"581","version_date":"1994-11-30","article_text":"1. Права одаряемого, которому по договору дарения обещан дар, не переходят к его наследникам (правопреемникам), если иное не предусмотрено договором дарения.\n\n2. Обязанности дарителя, обещавшего дарение, переходят к его наследникам (правопреемникам), если иное не предусмотрено договором дарения.","article_title":"Статья 581. Правопреемство при обещании дарения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d156d162893aba7f33a3a8a78cb939ef3d7eb6f843256ddc24d338f096ad1b87"},{"code_id":"GK_RF_2","article_number":"582","version_date":"1994-11-30","article_text":"Юридическое лицо, принимающее пожертвование, для использования которого установлено определенное назначение, должно вести обособленный учет всех операций по использованию пожертвованного имущества.","article_title":"Статья 582. Пожертвования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3d36ba383c6c48f61174d52e3a45842ffcae08be88af4557e098cd9df2b758b8"}]$law7v013$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text)) insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at) select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
    commit;
